def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seeds = set()
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dc in (-1, 1):
                nc = c + dc
                if 0 <= nc < w and grid[r + 1][nc] == color:
                    seeds.add((color, dc, r, c))
    for color, dc, r, c in seeds:
        rr, cc = r - 1, c - dc
        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
            out[rr][cc] = color
            rr -= 1
            cc -= dc
        rr, cc = r + 2, c + 2 * dc
        while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
            out[rr][cc] = color
            rr += 1
            cc += dc
    return out

